1	interface Item {
2	  type: string;
3	  material?: string;
4	  cursed?: boolean;
5	  enchantment?: number;
6	}
7	
8	interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	interface ClaimStep {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	}
23	
24	type Step = QuoteStep | ClaimStep;
25	
26	interface Customer {
27	  yearsWithMHPCO: number;
28	}
29	
30	interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	const BASE_PREMIUM: Record<string, number> = {
36	  sword: 100,
37	  amulet: 60,
38	  staff: 80,
39	  potion: 40,
40	};
41	
42	const INSURANCE_VALUE: Record<string, number> = {
43	  sword: 1000,
44	  amulet: 600,
45	  staff: 800,
46	  potion: 400,
47	  rune: 250,
48	  moonstone: 250,
49	};
50	
51	const DEDUCTIBLE = 100;
52	const CAP_MULTIPLIER = 2;
53	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
54	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
55	
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	const FOLLOWUP_DISCOUNT_RATE = 0.15;
63	const PROCESSING_FEE = 5;
64	
65	const curseSurchargeFor = (item: Item): number =>
66	  item.cursed ? BASE_PREMIUM[item.type] * CURSE_SURCHARGE_RATE : 0;
67	
68	const highEnchantmentSurchargeFor = (item: Item): number =>
69	  item.enchantment !== undefined &&
70	  item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD
71	    ? BASE_PREMIUM[item.type] * HIGH_ENCHANTMENT_SURCHARGE_RATE
72	    : 0;
73	
74	const sumSurcharges = (
75	  items: Item[],
76	  surchargeFor: (item: Item) => number,
77	): number => items.reduce((sum, item) => sum + surchargeFor(item), 0);
78	
79	const COMPONENT_TYPES = ["rune", "moonstone"];
80	const COMPONENT_PREMIUM = 25;
81	const COMPONENT_BLOCK_SIZE = 3;
82	const COMPONENT_BLOCK_PREMIUM = 60;
83	
84	const isComponent = (item: { type: string }): boolean =>
85	  COMPONENT_TYPES.includes(item.type);
86	
87	const sumComponentPremium = (count: number): number =>
88	  count === COMPONENT_BLOCK_SIZE
89	    ? COMPONENT_BLOCK_PREMIUM
90	    : count * COMPONENT_PREMIUM;
91	
92	const countByType = (items: { type: string }[]): Map<string, number> => {
93	  const counts = new Map<string, number>();
94	  for (const item of items) {
95	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
96	  }
97	  return counts;
98	};
99	
100	const sumBasePremiums = (items: { type: string }[]): number => {
101	  let total = 0;
102	  for (const [type, count] of countByType(items)) {
103	    total += isComponent({ type })
104	      ? sumComponentPremium(count)
105	      : BASE_PREMIUM[type] * count;
106	  }
107	  return total;
108	};
109	
110	// Item-specific surcharges: each depends on a single item's attributes.
111	const itemSurchargesFor = (items: Item[]): number =>
112	  sumSurcharges(items, curseSurchargeFor) +
113	  sumSurcharges(items, highEnchantmentSurchargeFor);
114	
115	// Policy-wide adjustments: each is a rate applied to the whole policy base.
116	const policyAdjustmentsFor = (
117	  policyBase: number,
118	  customer: Customer,
119	  isFollowUp: boolean,
120	): number => {
121	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
122	  const loyaltyDiscount =
123	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD
124	      ? policyBase * LOYALTY_DISCOUNT_RATE
125	      : 0;
126	  const followUpDiscount = isFollowUp ? policyBase * FOLLOWUP_DISCOUNT_RATE : 0;
127	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
128	};
129	
130	const quotePremium = (
131	  step: QuoteStep,
132	  customer: Customer,
133	  isFollowUp: boolean,
134	): number => {
135	  const policyBase = sumBasePremiums(step.items);
136	  const premium =
137	    policyBase +
138	    itemSurchargesFor(step.items) +
139	    policyAdjustmentsFor(policyBase, customer, isFollowUp) +
140	    PROCESSING_FEE;
141	  return Math.ceil(premium);
142	};
143	
144	const insuranceSumOf = (items: Item[]): number =>
145	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
146	
147	const isHighEnchantment = (item: Item): boolean =>
148	  item.enchantment !== undefined &&
149	  item.enchantment >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
150	
151	// Fraction of the damage amount reimbursed, before the deductible.
152	// This is the seam the material/enchantment claim rules extend: add new
153	// clauses here in precedence order (high-enchantment 50% wins over any
154	// future full-reimbursement clause).
155	const reimbursementRateFor = (insuredItem: Item): number =>
156	  isHighEnchantment(insuredItem) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : 1;
157	
158	// Per-damage payout: reimbursable amount after the deductible.
159	const payoutForDamage = (damage: Damage, insuredItem: Item): number => {
160	  const reimbursable = damage.amount * reimbursementRateFor(insuredItem);
161	  return Math.max(0, reimbursable - DEDUCTIBLE);
162	};
163	
164	const insuredItemFor = (damage: Damage, policy: QuoteStep): Item =>
165	  policy.items.find((item) => item.type === damage.itemType) as Item;
166	
167	// Resolve the insured item for a damage, then compute its payout.
168	const payoutForClaimDamage = (damage: Damage, policy: QuoteStep): number =>
169	  payoutForDamage(damage, insuredItemFor(damage, policy));
170	
171	const sumClaimPayout = (step: ClaimStep, policy: QuoteStep): number =>
172	  step.incident.damages.reduce(
173	    (sum, damage) => sum + payoutForClaimDamage(damage, policy),
174	    0,
175	  );
176	
177	const capFor = (policy: QuoteStep): number =>
178	  CAP_MULTIPLIER * insuranceSumOf(policy.items);
179	
180	const processClaim = (
181	  step: ClaimStep,
182	  policy: QuoteStep,
183	  remainingCap: number,
184	): { payout: number; remainingCap: number } => {
185	  const desired = Math.floor(sumClaimPayout(step, policy));
186	  const payout = Math.min(desired, remainingCap);
187	  return { payout, remainingCap: remainingCap - payout };
188	};
189	
190	// Mutable state threaded through the steps of a single scenario run:
191	// how many quotes have been seen (for the follow-up discount) and the
192	// unused payout cap still available on each policy.
193	interface ScenarioState {
194	  quoteCount: number;
195	  remainingCapByPolicy: Map<number, number>;
196	}
197	
198	const assertKnownItems = (items: Item[]): void => {
199	  for (const item of items) {
200	    if (!(item.type in INSURANCE_VALUE)) {
201	      throw new Error(`Unknown item type: ${item.type}`);
202	    }
203	  }
204	};
205	
206	const handleQuote = (
207	  step: QuoteStep,
208	  index: number,
209	  customer: Customer,
210	  state: ScenarioState,
211	): unknown => {
212	  assertKnownItems(step.items);
213	  const isFollowUp = state.quoteCount > 0;
214	  state.quoteCount += 1;
215	  state.remainingCapByPolicy.set(index, capFor(step));
216	  return { premium: quotePremium(step, customer, isFollowUp) };
217	};
218	
219	const handleClaim = (
220	  step: ClaimStep,
221	  steps: Step[],
222	  state: ScenarioState,
223	): unknown => {
224	  const policy = steps[step.policy] as QuoteStep;
225	  const remainingCap =
226	    state.remainingCapByPolicy.get(step.policy) ?? capFor(policy);
227	  const result = processClaim(step, policy, remainingCap);
228	  state.remainingCapByPolicy.set(step.policy, result.remainingCap);
229	  return result;
230	};
231	
232	export const runScenario = (scenario: Scenario): unknown => {
233	  const state: ScenarioState = {
234	    quoteCount: 0,
235	    remainingCapByPolicy: new Map<number, number>(),
236	  };
237	  const results = scenario.steps.map((step, index) =>
238	    step.op === "quote"
239	      ? handleQuote(step, index, scenario.customer, state)
240	      : handleClaim(step, scenario.steps, state),
241	  );
242	  return { results };
243	};
